def globMatch(s, pattern):
    toks = []
    i, m = 0, len(pattern)
    while i < m:
        c = pattern[i]
        if c == '*':
            toks.append(('*', None))
            i += 1
        elif c == '?':
            toks.append(('?', None))
            i += 1
        elif c == '[':
            i += 1
            neg = False
            if pattern[i] == '^':
                neg = True
                i += 1
            ranges = []
            while pattern[i] != ']':
                if pattern[i + 1] == '-':
                    ranges.append((pattern[i], pattern[i + 2]))
                    i += 3
                else:
                    ranges.append((pattern[i], pattern[i]))
                    i += 1
            i += 1
            toks.append(('[', (neg, ranges)))
        else:
            toks.append(('c', c))
            i += 1

    def hit(t, ch):
        kind, data = t
        if kind == '?':
            return True
        if kind == 'c':
            return data == ch
        neg, ranges = data
        inside = False
        for lo, hi in ranges:
            if lo <= ch <= hi:
                inside = True
                break
        return inside != neg

    n, k = len(s), len(toks)
    i = j = 0
    star = -1
    mark = 0
    while i < n:
        if j < k and toks[j][0] == '*':
            star = j
            mark = i
            j += 1
        elif j < k and hit(toks[j], s[i]):
            i += 1
            j += 1
        elif star != -1:
            mark += 1
            i = mark
            j = star + 1
        else:
            return False
    while j < k and toks[j][0] == '*':
        j += 1
    return j == k
